Here's a self-contained `CheckoutPage` component (React + TypeScript) with plain CSS — no backend wiring, just local form state, validation, and a `onPay` callback you can hook up to your payment flow.

**`CheckoutPage.tsx`**
```tsx
import React, { useMemo, useState } from 'react';
import './CheckoutPage.css';

export interface CartItem {
  id: string;
  name: string;
  price: number;
  quantity: number;
  imageUrl?: string;
}

export interface DeliveryAddress {
  fullName: string;
  street: string;
  city: string;
  postalCode: string;
  country: string;
  phone: string;
}

interface CheckoutPageProps {
  cartItems: CartItem[];
  onBackToCart: () => void;
  onPay: (address: DeliveryAddress) => void;
  isProcessing?: boolean;
  shippingCost?: number;
}

type AddressErrors = Partial<Record<keyof DeliveryAddress, string>>;

const EMPTY_ADDRESS: DeliveryAddress = {
  fullName: '',
  street: '',
  city: '',
  postalCode: '',
  country: '',
  phone: '',
};

function formatPrice(value: number): string {
  return `$${value.toFixed(2)}`;
}

function validateAddress(address: DeliveryAddress): AddressErrors {
  const errors: AddressErrors = {};

  if (!address.fullName.trim()) {
    errors.fullName = 'Full name is required';
  }
  if (!address.street.trim()) {
    errors.street = 'Street address is required';
  }
  if (!address.city.trim()) {
    errors.city = 'City is required';
  }
  if (!address.postalCode.trim()) {
    errors.postalCode = 'Postal code is required';
  }
  if (!address.country.trim()) {
    errors.country = 'Country is required';
  }
  if (!address.phone.trim()) {
    errors.phone = 'Phone number is required';
  } else if (!/^[+\d][\d\s-]{6,}$/.test(address.phone.trim())) {
    errors.phone = 'Enter a valid phone number';
  }

  return errors;
}

export default function CheckoutPage({
  cartItems,
  onBackToCart,
  onPay,
  isProcessing = false,
  shippingCost = 5.99,
}: CheckoutPageProps) {
  const [address, setAddress] = useState<DeliveryAddress>(EMPTY_ADDRESS);
  const [errors, setErrors] = useState<AddressErrors>({});
  const [touched, setTouched] = useState<Partial<Record<keyof DeliveryAddress, boolean>>>({});

  const subtotal = useMemo(
    () => cartItems.reduce((sum, item) => sum + item.price * item.quantity, 0),
    [cartItems]
  );
  const effectiveShipping = cartItems.length === 0 ? 0 : shippingCost;
  const total = subtotal + effectiveShipping;

  const handleChange = (field: keyof DeliveryAddress) => (
    e: React.ChangeEvent<HTMLInputElement>
  ) => {
    setAddress((prev) => ({ ...prev, [field]: e.target.value }));
  };

  const handleBlur = (field: keyof DeliveryAddress) => () => {
    setTouched((prev) => ({ ...prev, [field]: true }));
    setErrors(validateAddress(address));
  };

  const handleSubmit = (e: React.FormEvent) => {
    e.preventDefault();

    const validationErrors = validateAddress(address);
    setErrors(validationErrors);
    setTouched({
      fullName: true,
      street: true,
      city: true,
      postalCode: true,
      country: true,
      phone: true,
    });

    if (Object.keys(validationErrors).length === 0 && cartItems.length > 0) {
      onPay(address);
    }
  };

  const fieldError = (field: keyof DeliveryAddress) =>
    touched[field] ? errors[field] : undefined;

  return (
    <div className="checkout-page">
      <div className="checkout-header">
        <button type="button" className="back-link" onClick={onBackToCart}>
          &larr; Back to cart
        </button>
        <h1>Checkout</h1>
      </div>

      <div className="checkout-layout">
        <section className="checkout-section cart-summary" aria-labelledby="cart-heading">
          <h2 id="cart-heading">Your items</h2>

          {cartItems.length === 0 ? (
            <p className="empty-cart">Your cart is empty.</p>
          ) : (
            <ul className="cart-list">
              {cartItems.map((item) => (
                <li key={item.id} className="cart-item">
                  <div className="cart-item-image">
                    {item.imageUrl ? (
                      <img src={item.imageUrl} alt={item.name} />
                    ) : (
                      <div className="cart-item-placeholder" aria-hidden="true" />
                    )}
                  </div>
                  <div className="cart-item-details">
                    <span className="cart-item-name">{item.name}</span>
                    <span className="cart-item-qty">Qty: {item.quantity}</span>
                  </div>
                  <span className="cart-item-price">
                    {formatPrice(item.price * item.quantity)}
                  </span>
                </li>
              ))}
            </ul>
          )}

          <div className="totals">
            <div className="totals-row">
              <span>Subtotal</span>
              <span>{formatPrice(subtotal)}</span>
            </div>
            <div className="totals-row">
              <span>Shipping</span>
              <span>{formatPrice(effectiveShipping)}</span>
            </div>
            <div className="totals-row totals-row-final">
              <span>Total</span>
              <span>{formatPrice(total)}</span>
            </div>
          </div>
        </section>

        <section className="checkout-section address-form" aria-labelledby="address-heading">
          <h2 id="address-heading">Delivery address</h2>

          <form onSubmit={handleSubmit} noValidate>
            <div className="form-field">
              <label htmlFor="fullName">Full name</label>
              <input
                id="fullName"
                type="text"
                value={address.fullName}
                onChange={handleChange('fullName')}
                onBlur={handleBlur('fullName')}
                aria-invalid={Boolean(fieldError('fullName'))}
              />
              {fieldError('fullName') && (
                <span className="field-error">{fieldError('fullName')}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="street">Street address</label>
              <input
                id="street"
                type="text"
                value={address.street}
                onChange={handleChange('street')}
                onBlur={handleBlur('street')}
                aria-invalid={Boolean(fieldError('street'))}
              />
              {fieldError('street') && (
                <span className="field-error">{fieldError('street')}</span>
              )}
            </div>

            <div className="form-row">
              <div className="form-field">
                <label htmlFor="city">City</label>
                <input
                  id="city"
                  type="text"
                  value={address.city}
                  onChange={handleChange('city')}
                  onBlur={handleBlur('city')}
                  aria-invalid={Boolean(fieldError('city'))}
                />
                {fieldError('city') && (
                  <span className="field-error">{fieldError('city')}</span>
                )}
              </div>

              <div className="form-field">
                <label htmlFor="postalCode">Postal code</label>
                <input
                  id="postalCode"
                  type="text"
                  value={address.postalCode}
                  onChange={handleChange('postalCode')}
                  onBlur={handleBlur('postalCode')}
                  aria-invalid={Boolean(fieldError('postalCode'))}
                />
                {fieldError('postalCode') && (
                  <span className="field-error">{fieldError('postalCode')}</span>
                )}
              </div>
            </div>

            <div className="form-field">
              <label htmlFor="country">Country</label>
              <input
                id="country"
                type="text"
                value={address.country}
                onChange={handleChange('country')}
                onBlur={handleBlur('country')}
                aria-invalid={Boolean(fieldError('country'))}
              />
              {fieldError('country') && (
                <span className="field-error">{fieldError('country')}</span>
              )}
            </div>

            <div className="form-field">
              <label htmlFor="phone">Phone number</label>
              <input
                id="phone"
                type="tel"
                value={address.phone}
                onChange={handleChange('phone')}
                onBlur={handleBlur('phone')}
                aria-invalid={Boolean(fieldError('phone'))}
              />
              {fieldError('phone') && (
                <span className="field-error">{fieldError('phone')}</span>
              )}
            </div>

            <button
              type="submit"
              className="pay-button"
              disabled={isProcessing || cartItems.length === 0}
            >
              {isProcessing ? 'Processing…' : `Pay ${formatPrice(total)}`}
            </button>
          </form>
        </section>
      </div>
    </div>
  );
}
```

